def count_zeros(n):
    return str(n).count('0')

def solve_small_L(L):
    import itertools
    max_A = 0
    digits = '123456789'
    for p in itertools.product(digits, repeat=L):
        M = int("".join(p))
        n = 1
        while n <= M:
            q = M // n
            if q == 0: break
            a = count_zeros(q)
            if a > max_A:
                max_A = a
            n = M // q + 1
    return max_A

print(f"L=6, max_A={solve_small_L(6)}")
